pragma solidity >=0.8.0;
contract StoragePackingProbe {
    string public text;
    uint256 public wide;
    uint8 public a;
    bool public b;
    int64 public c;
    uint8 public d;

    event Packed(uint8 a, bool b, int64 c, uint8 d);

    function setSmall(uint8 _a, bool _b, int64 _c, uint8 _d) public {
        a = _a; b = _b; c = _c; d = _d;
        emit Packed(_a, _b, _c, _d);
    }
    function setWide(uint256 w) public { wide = w; }
    function setText(string memory t) public { text = t; }
    function bumpA() public { a = a + 1; }
    function clearA() public { delete a; }
}
